"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/empty-states/variants/01-archive";
const variants = {"archive": Variant0};
export interface ArtemisEmptyStatesProps { className?: string; variant?: "archive"; }
export function ArtemisEmptyStates({ className, variant = "archive" }: ArtemisEmptyStatesProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><View/></ArtemisScope>; }

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, type Transition, useReducedMotion } from "motion/react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL } from "../../../lib/ease";
const SETTLE: Transition = ARTEMIS_SPRING_PANEL;
const DRAW: Transition = { duration: 0.4, ease: ARTEMIS_EASE_OUT };
const LABELS: Transition = { duration: 0.15, ease: "easeOut" };
const INSTANT: Transition = { duration: 0 };
const OUTLINE = [
    "M88 58 174 12l91 54-87 47Z",
    "m88 58 90 55v153l-90-53Z",
    "m178 113 87-47v151l-87 49Z",
    "m95 217-10 6v17l13 8",
    "m246 227 12-7v16l-12 7Z",
    "m88 72 90 54 87-47",
    "m88 136 90 54 87-48",
];
export default function EmptyStatesArchive() {
    const reduce = useReducedMotion();
    const [ready, setReady] = useState(Boolean(reduce));
    const [boxReady, setBoxReady] = useState(Boolean(reduce));
    const [labelsReady, setLabelsReady] = useState(Boolean(reduce));
    useEffect(() => {
        if (reduce) {
            setReady(true);
            setBoxReady(true);
            setLabelsReady(true);
            return;
        }
        const timer = window.setTimeout(() => setReady(true), 80);
        const boxTimer = window.setTimeout(() => setBoxReady(true), 260);
        const labelsTimer = window.setTimeout(() => setLabelsReady(true), 420);
        return () => {
            window.clearTimeout(timer);
            window.clearTimeout(boxTimer);
            window.clearTimeout(labelsTimer);
        };
    }, [reduce]);
    const t = (transition: Transition): Transition => (reduce ? INSTANT : transition);
    return (<>
      <section className="art:mx-auto art:flex art:w-full art:max-w-[520px] art:flex-col art:items-center art:justify-center art:text-center art:text-foreground">
        <motion.div aria-hidden="true" className="art:relative art:mb-5 art:w-full art:max-w-[205px] art:text-foreground" initial={{ opacity: 0, y: 12 }} animate={ready ? { opacity: 1, y: 0 } : undefined} transition={t(SETTLE)} whileHover={reduce ? undefined : "hover"} variants={{ hover: { y: -3, transition: SETTLE } }}>
          <svg viewBox="0 0 320 300" className="art:w-full" role="presentation">
            <g fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.6">
              {OUTLINE.map((d) => (<motion.path key={d} d={d} initial={{ pathLength: 0, opacity: 0 }} animate={ready ? { pathLength: 1, opacity: 1 } : undefined} transition={t(DRAW)}/>))}
            </g>
            <motion.g fill="var(--artemis-background)" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.6" initial={{ x: 22, y: -14, opacity: 0 }} animate={boxReady ? { x: -18, y: 13, opacity: 1 } : undefined} transition={t(SETTLE)} variants={{ hover: { x: -28, y: 19, transition: SETTLE } }}>
              <path d="m106 139 72 43 69-38-70-42Z"/>
              <path d="m106 139 71 43v72l-71-42Z"/>
              <path d="m177 182 70-38v70l-70 40Z"/>
              <path d="m118 145 59 35 57-31-59-35Z" opacity="0.45"/>
            </motion.g>
            <motion.g fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.8" initial={{ opacity: 0 }} animate={labelsReady ? { opacity: 1 } : undefined} transition={t(LABELS)}>
              <path d="m126 175 21 12 14-8"/>
              <path d="m118 159 22 13 14-8"/>
              <path d="m119 91 23 14 15-8-23-14Z"/>
              <path d="m126 118 21 13 14-8"/>
            </motion.g>
          </svg>
        </motion.div>
        <div className="art:max-w-sm">
          <h2 className="art:text-balance art:tracking-[-0.03em] art:text-4xl art:font-medium">{"No data yet"}</h2>
          <p className="art:mx-auto art:mt-2 art:max-w-xs art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
            {"Create a record or import your existing data."}
          </p>
          <ArtemisButton size="sm" className="art:mt-4 art:h-9">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-plus art:size-3.5" aria-hidden="true">
              <path d="M5 12h14"/>
              <path d="M12 5v14"/>
            </svg>
            {"Add data"}
          </ArtemisButton>
        </div>
      </section>
    </>);
}
